use std::{path::PathBuf, time::Instant};
use windows::Win32::{
    Foundation::FILETIME,
    System::Threading::{GetCurrentProcess, GetProcessTimes},
};

fn cpu_seconds() -> f64 {
    let (mut created, mut exited, mut kernel, mut user) = (
        FILETIME::default(), FILETIME::default(), FILETIME::default(), FILETIME::default(),
    );
    unsafe {
        GetProcessTimes(GetCurrentProcess(), &mut created, &mut exited, &mut kernel, &mut user).unwrap();
    }
    let ticks = |time: FILETIME| ((time.dwHighDateTime as u64) << 32) | time.dwLowDateTime as u64;
    (ticks(kernel) + ticks(user)) as f64 / 10_000_000.0
}

fn main() {
    let root = PathBuf::from(std::env::args_os().nth(1).expect("project root"));
    let mut samples = Vec::new();
    for index in 0..12 {
        let cpu = cpu_seconds();
        let started = Instant::now();
        let result = gwt::issue_monitor_worker::read_execution_observations(&root, &[]);
        let elapsed = started.elapsed().as_secs_f64() * 1000.0;
        let cpu = cpu_seconds() - cpu;
        assert!(result.is_empty());
        samples.push(serde_json::json!({"index":index,"wall_ms":elapsed,"cpu_seconds":cpu,"result_count":result.len()}));
    }
    println!("{}", serde_json::json!({"project_root":root,"input_issues":[],"samples":samples}));
}
